import { ref, onMounted, onBeforeUnmount, computed } from 'vue';
import DockerContainers from '@/components/Container/DockerContainers.vue'; // 修改为你的实际路径
import axios from 'axios';
import * as echarts from 'echarts';

// refs

export default {
  __name: 'MonitorView',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const dockerContainersRef = ref(null);
    const containers = ref([]); // 容器列表
    const selectedContainer = ref(''); // 当前选中的容器
    const bandwidthChartRef = ref(null);
    const networkChartRef = ref(null);
    const bandwidthRxData = ref([]);
    const bandwidthTxData = ref([]);
    let bandwidthChart = null;
    let networkChart = null;
    let intervalId = null;

    // 图表数据
    const timeData = ref([]);
    const bandwidthData = ref([]);
    const rxData = ref([]);
    const txData = ref([]);
    const fetchContainers = async () => {
      if (dockerContainersRef.value) {
        await dockerContainersRef.value.fetchContainers();
        containers.value = dockerContainersRef.value.containers;
      }
    };

    // 开始监控
    const startMonitoring = () => {
      clearInterval(intervalId);
      timeData.value = [];
      bandwidthData.value = [];
      rxData.value = [];
      txData.value = [];
      bandwidthRxData.value = [];
      bandwidthTxData.value = [];
      updateCharts();
      intervalId = setInterval(async () => {
        if (!selectedContainer.value) return;
        const timestamp = new Date().toLocaleTimeString();
        try {
          const bandwidthRes = await axios.get(`http://localhost:8081/stats/bandwidth/${selectedContainer.value}?interval=1000`);
          const statsRes = await axios.get(`http://localhost:8081/stats/networkStats/${selectedContainer.value}`);
          timeData.value.push(timestamp);
          bandwidthRxData.value.push(bandwidthRes.data.rxBytesPerSec);
          bandwidthTxData.value.push(bandwidthRes.data.txBytesPerSec);
          rxData.value.push(statsRes.data.rxBytes);
          txData.value.push(statsRes.data.txBytes);
          if (timeData.value.length > 20) {
            timeData.value.shift();
            bandwidthData.value.shift();
            rxData.value.shift();
            txData.value.shift();
          }
          updateCharts();
        } catch (err) {
          console.error('监控数据获取失败', err);
        }
      }, 1000);
    };

    // 更新图表
    const updateCharts = () => {
      if (!bandwidthChart || !networkChart) {
        bandwidthChart = echarts.init(bandwidthChartRef.value);
        networkChart = echarts.init(networkChartRef.value);
      }
      bandwidthChart.setOption({
        title: {
          text: '容器带宽使用率 (Bytes/s)'
        },
        tooltip: {
          trigger: 'axis'
        },
        xAxis: {
          type: 'category',
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: bandwidthRxData.value,
          type: 'line',
          name: '下载速率 RX',
          smooth: true,
          areaStyle: {}
        }, {
          data: bandwidthTxData.value,
          type: 'line',
          name: '上传速率 TX',
          smooth: true,
          areaStyle: {}
        }]
      });
      networkChart.setOption({
        title: {
          text: '网络收发字节数 (累计)'
        },
        tooltip: {
          trigger: 'axis'
        },
        xAxis: {
          type: 'category',
          data: timeData.value
        },
        yAxis: {
          type: 'value'
        },
        series: [{
          data: rxData.value,
          type: 'line',
          name: '接收字节 RX',
          smooth: true
        }, {
          data: txData.value,
          type: 'line',
          name: '发送字节 TX',
          smooth: true
        }]
      });
    };

    // 计算可用的运行中容器
    const availableContainers = computed(() => {
      return containers.value.filter(c => c.status?.includes('Up'));
    });
    const formatContainerName = name => {
      return name.replace(/^\//, '');
    };
    const formatStatus = status => {
      return status?.includes('Up') ? '运行中' : '已停止';
    };
    onMounted(async () => {
      // 初次获取容器列表
      await fetchContainers();
      // 设置定时器，用于定期更新其他监控数据
      intervalId = setInterval(async () => {
        await fetchContainers();
      }, 1000);
    });

    // 清理定时器，防止内存泄漏
    onBeforeUnmount(() => {
      if (intervalId) {
        clearInterval(intervalId);
      }
    });
    const __returned__ = {
      dockerContainersRef,
      containers,
      selectedContainer,
      bandwidthChartRef,
      networkChartRef,
      bandwidthRxData,
      bandwidthTxData,
      get bandwidthChart() {
        return bandwidthChart;
      },
      set bandwidthChart(v) {
        bandwidthChart = v;
      },
      get networkChart() {
        return networkChart;
      },
      set networkChart(v) {
        networkChart = v;
      },
      get intervalId() {
        return intervalId;
      },
      set intervalId(v) {
        intervalId = v;
      },
      timeData,
      bandwidthData,
      rxData,
      txData,
      fetchContainers,
      startMonitoring,
      updateCharts,
      availableContainers,
      formatContainerName,
      formatStatus,
      ref,
      onMounted,
      onBeforeUnmount,
      computed,
      DockerContainers,
      get axios() {
        return axios;
      },
      get echarts() {
        return echarts;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
